package com.library.ui;
import com.library.model.Member; import com.library.service.MemberService; import javax.swing.*; import javax.swing.table.DefaultTableModel; import java.awt.*;
public class MemberManagementFrame extends JFrame { private final MemberService service=new MemberService();private final JTextField search=new JTextField(16),enrollment=new JTextField(),name=new JTextField(),email=new JTextField(),phone=new JTextField(),course=new JTextField(),dept=new JTextField(),semester=new JTextField();private final JPasswordField password=new JPasswordField();private final DefaultTableModel model=new DefaultTableModel(new String[]{"Enrollment No.","Name","Email","Phone","Course","Department","Sem","Status"},0){public boolean isCellEditable(int r,int c){return false;}};private final JTable table=new JTable(model);private long selected;
 public MemberManagementFrame(){super("Member Management");setSize(1100,720);setMinimumSize(new Dimension(950,650));setLocationRelativeTo(null);setDefaultCloseOperation(DISPOSE_ON_CLOSE);JPanel top=new JPanel(new BorderLayout());JPanel searchRow=new JPanel(new FlowLayout(FlowLayout.LEFT,10,10));searchRow.setBackground(Color.WHITE);searchRow.add(new JLabel("Search by enrollment no., name, email or phone"));search.setPreferredSize(new Dimension(300,34));searchRow.add(search);JButton s=UI.button("Search");s.addActionListener(e->load());searchRow.add(s);top.add(UI.header(this,"Member Management","Register, update and manage library members"),BorderLayout.NORTH);top.add(searchRow,BorderLayout.CENTER);add(top,BorderLayout.NORTH);UI.table(table);JPanel f=new JPanel(new GridLayout(0,4,12,8));f.setBackground(Color.WHITE);f.setBorder(BorderFactory.createTitledBorder(BorderFactory.createEmptyBorder(),"Student Details",0,0,new Font("Segoe UI",Font.BOLD,16),UI.NAVY));for(JComponent c:new JComponent[]{new JLabel("Enrollment Number"),enrollment,new JLabel("Full Name"),name,new JLabel("Email Address"),email,new JLabel("Password (new student)"),password,new JLabel("Phone"),phone,new JLabel("Course"),course,new JLabel("Department"),dept,new JLabel("Semester"),semester,button("Add Student",0),button("Update Selected",1),button("Deactivate",2)})f.add(c);JScrollPane formScroll=new JScrollPane(f);formScroll.setPreferredSize(new Dimension(1,285));JSplitPane split=new JSplitPane(JSplitPane.VERTICAL_SPLIT,new JScrollPane(table),formScroll);split.setResizeWeight(.58);split.setDividerLocation(350);add(split,BorderLayout.CENTER);table.getSelectionModel().addListSelectionListener(e->select());load();} private JButton button(String x,int mode){JButton b=UI.button(x);b.addActionListener(e->{try{if(mode==2){if(selected==0)throw new IllegalArgumentException("Select a student first.");service.deactivate(selected);UI.info(this,"Student deactivated.");}else if(mode==0)service.add(read(),new String(password.getPassword()));else service.update(read());load();clear();}catch(Exception z){UI.error(this,z);}});return b;} private Member read(){try{long id=selected==0?Long.parseLong(enrollment.getText().trim()):selected;if(id<=0)throw new NumberFormatException();return new Member(0,name.getText(),email.getText(),null,"ACTIVE",id,phone.getText(),course.getText(),dept.getText(),Integer.parseInt(semester.getText().trim()),null);}catch(NumberFormatException e){throw new IllegalArgumentException("Enrollment number and semester must be valid numbers.");}} private void load(){try{model.setRowCount(0);for(Member m:service.search(search.getText()))model.addRow(new Object[]{m.getMemberId(),m.getName(),m.getEmail(),m.getPhone(),m.getCourse(),m.getDepartment(),m.getSemester(),m.getStatus()});}catch(Exception e){UI.error(this,e);}} private void select(){if(table.getSelectedRow()<0)return;selected=((Number)model.getValueAt(table.getSelectedRow(),0)).longValue();Member m=service.get(selected);enrollment.setText(String.valueOf(m.getMemberId()));enrollment.setEditable(false);name.setText(m.getName());email.setText(m.getEmail());phone.setText(m.getPhone());course.setText(m.getCourse());dept.setText(m.getDepartment());semester.setText(String.valueOf(m.getSemester()));} private void clear(){selected=0;enrollment.setEditable(true);password.setText("");for(JTextField f:new JTextField[]{enrollment,name,email,phone,course,dept,semester})f.setText("");} }
